import React, { useState } from "react";
import axios from "axios";

export default function AddOrder() {
  const [firstName, setFirstName] = useState("");
  const [lastName, setLastName] = useState("");
  const [email, setEmail] = useState("");
  const [phoneNumber, setPhoneNumber] = useState("");
  const [address, setAddress] = useState("");
  const [city, setCity] = useState("");
  const [orderId, setOrderId] = useState("");
  const [specialInstructions, setSpecialInstructions] = useState("");
  const [pickupTime, setPickupTime] = useState("");
  const [orderStatus, setOrderStatus] = useState("");

  function sendData(e) {
    e.preventDefault();

    const newOrder = {
      firstName,
      lastName,
      email,
      phoneNumber,
      address,
      city,
      orderId,
      specialInstructions,
      pickupTime,
      orderStatus,
    };

    axios
      .post("http://Localhost:5000/orders/add", newOrder)
      .then(() => {
        alert("Order Added");
        setFirstName("");
        setLastName("");
        setEmail("");
        setPhoneNumber("");
        setAddress("");
        setCity("");
        setOrderId("");
        setSpecialInstructions("");
        setPickupTime("");
        setOrderStatus("");
      })
      .catch((err) => {
        alert(err);
      });
  }

  const containerStyle = {
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    minHeight: "100vh",
    backgroundColor: "#f0f0f0",
    padding: "20px",
  };

  const formContainerStyle = {
    backgroundColor: "white",
    padding: "20px",
    borderRadius: "10px",
    boxShadow: "0px 4px 10px rgba(0, 0, 0, 0.1)",
    width: "100%",
    maxWidth: "600px",
    boxSizing: "border-box",
    overflowY: "auto",
    maxHeight: "90vh",
    margin: "auto", // Center the form horizontally
  };

  const formGroupStyle = {
    marginBottom: "15px",
  };

  const formControlStyle = {
    width: "100%",
    padding: "10px",
    border: "1px solid #ccc",
    borderRadius: "5px",
    boxSizing: "border-box",
  };

  const buttonContainerStyle = {
    display: "flex",
    justifyContent: "flex-end",
    marginTop: "20px",
  };

  const buttonStyle = {
    backgroundColor: "#b30000",
    color: "white",
    padding: "10px 20px",
    border: "none",
    borderRadius: "5px",
    cursor: "pointer",
    fontSize: "16px",
  };

  const errorStyle = {
    color: "red",
    marginTop: "5px",
  };

  return (
    <div style={containerStyle}>
      <form style={formContainerStyle} onSubmit={sendData}>
        <div style={formGroupStyle}>
          <label htmlFor="InputFirstName">First Name</label>
          <input
            type="text"
            style={formControlStyle}
            id="InputFirstName"
            placeholder="Enter first name"
            onChange={(e) => setFirstName(e.target.value)}
            value={firstName}
          />
        </div>
        <div style={formGroupStyle}>
          <label htmlFor="InputLastName">Last Name</label>
          <input
            type="text"
            style={formControlStyle}
            id="InputLastName"
            placeholder="Enter last name"
            onChange={(e) => setLastName(e.target.value)}
            value={lastName}
          />
        </div>
        <div style={formGroupStyle}>
          <label htmlFor="InputEmail">Email</label>
          <input
            type="text"
            style={formControlStyle}
            id="InputEmail"
            placeholder="Enter the email"
            onChange={(e) => setEmail(e.target.value)}
            value={email}
          />
        </div>
        <div style={formGroupStyle}>
          <label htmlFor="InputPhoneNumber">Phone Number</label>
          <input
            type="text"
            style={formControlStyle}
            id="InputPhoneNumber"
            placeholder="Enter phone number"
            onChange={(e) => setPhoneNumber(e.target.value)}
            value={phoneNumber}
          />
        </div>
        <div style={formGroupStyle}>
          <label htmlFor="InputAddress">Address</label>
          <input
            type="text"
            style={formControlStyle}
            id="InputAddress"
            placeholder="Enter Address"
            onChange={(e) => setAddress(e.target.value)}
            value={address}
          />
        </div>
        <div style={formGroupStyle}>
          <label htmlFor="InputCity">City</label>
          <input
            type="text"
            style={formControlStyle}
            id="InputCity"
            placeholder="Enter city"
            onChange={(e) => setCity(e.target.value)}
            value={city}
          />
        </div>
        <div style={formGroupStyle}>
          <label htmlFor="InputOrderId">order Id</label>
          <input
            type="text"
            style={formControlStyle}
            id="InputOrderId"
            placeholder="Enter Order Id"
            onChange={(e) => setOrderId(e.target.value)}
            value={orderId}
          />
        </div>
        <div style={formGroupStyle}>
          <label htmlFor="InputSpecialInstructions">Special Instructions</label>
          <input
            type="text"
            style={formControlStyle}
            id="InputSpecialInstructions"
            placeholder="Enter special instructions"
            onChange={(e) => setSpecialInstructions(e.target.value)}
            value={specialInstructions}
          />
        </div>
        <div style={formGroupStyle}>
          <label htmlFor="InputPickupTime">Pickup Time</label>
          <input
            type="text"
            style={formControlStyle}
            id="InputPickupTime"
            placeholder="Enter pickup Time"
            onChange={(e) => setPickupTime(e.target.value)}
            value={pickupTime}
          />
        </div>
        <div style={formGroupStyle}>
          <label htmlFor="InputOrderStatus">Order Status</label>
          <input
            type="text"
            style={formControlStyle}
            id="InputOrderStatus"
            placeholder="Enter Order Status"
            onChange={(e) => setOrderStatus(e.target.value)}
            value={orderStatus}
          />
        </div>

        <div style={buttonContainerStyle}>
          <button type="submit" style={buttonStyle}>
            Submit
          </button>
        </div>
      </form>
    </div>
  );
}
